package app.dev.jokes_system.model;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

// Getters + Setters generated by lombok
@Getter
@Setter
@NoArgsConstructor
// Tells Spring that Joke is JPA entity, and it we'll be mapped to "joke" table
@Entity
// Tells Spring that the actual table name is "jokes", and not "joke"
@Table(name="jokes")
public class Joke {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Integer id;

    @Column(nullable = false)
    private String setup;

    @Column(nullable = false)
    private String punchline;

    @Column(nullable = false)
    private int minAge;

    @Column(nullable = false)
    private int rating;

    // Tells JPA to store and retrieve enum values using their names rather than numeric positions.
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private JokeCategory category;

    // Constructor
    public Joke(String setup, String punchline, int minAge, int rating, JokeCategory category){
        this.setup = setup;
        this.punchline = punchline;
        this.minAge = minAge;
        this.rating = rating;
        this.category = category;
    }

    @Override
    public String toString(){
        return this.setup + " ==> " + this.punchline;
    }
}
